from pathlib import Path
import base64,gzip

hp=Path('compat/x86_d3d9/ptar_d3d9_isolated_presenter.h')
pp=Path('compat/x86_d3d9/ptar_d3d9_proxy.cpp')
oldh=hp.read_text(encoding='utf-8')
p=pp.read_text(encoding='utf-8')

# HF10 applies after HF9. Lock the expected inherited topology before changing it.
for token in ('PtD3D9IsoCreateDisplayResourcesOnCallerThread','g_ptarD3D9IsoDisplayDevice','FG_ACTIVATION_PRESENTER_PREP_OK'):
    if token not in oldh+p:
        raise SystemExit('HF9 base gate missing: '+token)

HEADER_GZ_B64=''
HEADER=gzip.decompress(base64.b64decode(HEADER_GZ_B64)).decode('utf-8')
hp.write_text(HEADER,encoding='utf-8',newline='\n')

anchor='''    if(!g_ptarResolutionPolicy.enabled)
    {
        PtDiagLogA("CREATEDEVICE_PTAR_DISABLED_BY_CONFIG");
        return g_realCreateDevice(self,adapter,type,focus,flags,pp,out);
    }

    PTARResolutionPlan plan={};'''
replacement='''    if(!g_ptarResolutionPolicy.enabled)
    {
        PtDiagLogA("CREATEDEVICE_PTAR_DISABLED_BY_CONFIG");
        return g_realCreateDevice(self,adapter,type,focus,flags,pp,out);
    }

    // FIELDHOTFIX10: source and display worker intentionally share this D3D9
    // device. D3DCREATE_MULTITHREADED is the D3D9 runtime contract that makes
    // cross-thread API access safe. The exact-game fallback remains untouched
    // because PTAR does not attach on that path.
    const DWORD ptarCreateFlags=flags|D3DCREATE_MULTITHREADED;
    PtDiagLogA(
        "CREATEDEVICE_PTAR_FLAGS original=0x%08lX actual=0x%08lX same_device_presenter=1",
        (unsigned long)flags,(unsigned long)ptarCreateFlags);

    PTARResolutionPlan plan={};'''
if anchor not in p:
    raise SystemExit('proxy flags anchor missing')
p=p.replace(anchor,replacement,1)

old='''    HRESULT hr=g_realCreateDevice(
        self,adapter,type,focus,flags,&actual,out);'''
new='''    HRESULT hr=g_realCreateDevice(
        self,adapter,type,focus,ptarCreateFlags,&actual,out);'''
if old not in p: raise SystemExit('primary create anchor missing')
p=p.replace(old,new,1)
old='''        hr=g_realCreateDevice(
            self,adapter,type,focus,flags,&actual,out);'''
new='''        hr=g_realCreateDevice(
            self,adapter,type,focus,ptarCreateFlags,&actual,out);'''
if old not in p: raise SystemExit('retry create anchor missing')
p=p.replace(old,new,1)
p=p.replace('FG_ACTIVATION_PRESENTER_PREP_OK backend=D3D9EX_FLIPEX','FG_ACTIVATION_PRESENTER_PREP_OK backend=SAME_DEVICE_ADDITIONAL_SWAP',1)
pp.write_text(p,encoding='utf-8',newline='\n')

h=hp.read_text(encoding='utf-8')
p=pp.read_text(encoding='utf-8')
for token in ('CreateAdditionalSwapChain','D3DPRESENT_INTERVAL_ONE','D3DPRESENT_DONOTWAIT','IDirect3DSwapChain9','PTAR_D3D9_FG_ACTIVATION_STATE.txt','GENERATED_THEN_MATCHING_REAL'):
    if token not in h: raise SystemExit('HF10 presenter gate missing: '+token)
for obsolete in ('IDirect3D9Ex','IDirect3DDevice9Ex','CreateDeviceEx','PresentEx','PtD3D9IsoOpenSharedTexture','g_ptarD3D9IsoDisplayDevice'):
    if obsolete in h: raise SystemExit('HF10 obsolete second-device token remains: '+obsolete)
if 'flags|D3DCREATE_MULTITHREADED' not in p: raise SystemExit('HF10 source device is not multithread-safe')
if p.count('ptarCreateFlags') < 4: raise SystemExit('HF10 PTAR create flags patch incomplete')
print('D3D9_HF10_SAME_DEVICE_ASYNC_SWAP=PASS')
print('SECOND_D3D9EX_DEVICE=REMOVED')
print('DISPLAY_SWAP=ADDITIONAL_SAME_DEVICE_INTERVAL_ONE_DONOTWAIT')
print('ACTIVATION_STATE_ALWAYS_ON=PASS')
